app.post(
  '/api/me/password',
  requireAuth,
  authLimiter,
  ah(async (req, res) => {
    const { rows } = await query('SELECT password_hash FROM users WHERE id=$1', [req.user.id]);
    if (!(await bcrypt.compare(String(req.body.current || ''), rows[0].password_hash))) return res.status(400).json({ error: 'Current password is wrong' });
    const np = String(req.body.password || '');
    const pwe = pwProblem(np);
    if (pwe) return res.status(400).json({ error: pwe });
    // changing the password logs out every other device (token_version) and keeps this one signed in
    const nu = (await query('UPDATE users SET password_hash=$1, token_version=token_version+1 WHERE id=$2 RETURNING id,role,token_version', [await bcrypt.hash(np, 12), req.user.id])).rows[0];
    issueToken(res, nu);
    audit(req, 'password_changed', '');
    res.json({ ok: true });
  })
);

