const admin = express.Router();

/* ------------------------------ visual website editor (site_edits) ------------------------------ */
const pageKeyOk = (v) => typeof v === 'string' && /^(\*|\/[\w\-./]{0,80})$/.test(v);
function cleanEdit(d) {
  d = d && typeof d === 'object' ? d : {};
  const o = {};
  if (typeof d.text === 'string') o.text = d.text.slice(0, 3000);
  const n = Number(d.size); if (n >= 8 && n <= 140) o.size = Math.round(n * 10) / 10;
  if (typeof d.color === 'string' && /^#[0-9a-fA-F]{6}$/.test(d.color)) o.color = d.color;
  if (typeof d.bg === 'string' && /^#[0-9a-fA-F]{6}$/.test(d.bg)) o.bg = d.bg;
  if (d.bold === true) o.bold = true;
  if (['left', 'center', 'right'].includes(d.align)) o.align = d.align;
  if (d.hidden === true) o.hidden = true;
  if (typeof d.src === 'string' && d.src && imgUrlOk(d.src)) o.src = d.src.slice(0, 500);
  if (typeof d.href === 'string' && d.href && /^(https:\/\/[^\s<>"']+|\/[\w\-./?=&#]*)$/.test(d.href)) o.href = d.href.slice(0, 500);
  if (d.add && typeof d.add === 'object' && typeof d.add.after === 'string') o.add = { after: d.add.after.slice(0, 400), tag: ['p', 'h2', 'h3'].includes(d.add.tag) ? d.add.tag : 'p' };
  return o;
}
