/* home tabs (topics) and AI Learn & Use courses (topics of kind "aicourse") */
const topicUpload = upload.fields([{ name: 'icon', maxCount: 1 }, { name: 'cover', maxCount: 1 }]);
const kindOf = (v) => (v === 'aicourse' ? 'aicourse' : 'tab');
const urlFile = (u) => (u && u.startsWith('/uploads/') ? u.slice(9) : null);
admin.get(
  '/topics',
  ah(async (req, res) => {
    const { rows } = await query(
      `SELECT t.id,t.title,t.icon_url,t.cover_url,t.kind,t.sort_order,t.is_active,t.price::float AS price, COUNT(p.id)::int AS items
       FROM topics t LEFT JOIN products p ON p.topic_id=t.id WHERE ($1='all' OR t.kind=$1) GROUP BY t.id ORDER BY t.sort_order, t.id`,
      [req.query.kind === 'all' ? 'all' : kindOf(req.query.kind)]
    );
    res.json({ topics: rows });
  })
);
function topicFiles(req) {
  return { icon: req.files && req.files.icon && req.files.icon[0], cover: req.files && req.files.cover && req.files.cover[0] };
}
admin.post(
  '/topics',
  topicUpload,
  ah(async (req, res) => {
    const { icon, cover } = topicFiles(req);
    const drop = () => { if (icon) safeUnlink(UPLOADS, icon.filename); if (cover) safeUnlink(UPLOADS, cover.filename); };
    const title = cleanStr(req.body.title, 80);
    const price = Number(req.body.price === undefined || req.body.price === '' ? 199 : req.body.price);
    if (!(price > 0) || price > 1000000) { drop(); return res.status(400).json({ error: 'Enter a valid price' }); }
    if (!title) { drop(); return res.status(400).json({ error: 'Enter the name' }); }
    const r = await query('INSERT INTO topics(title,icon_url,cover_url,sort_order,is_active,price,kind) VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id', [
      title,
      icon ? '/uploads/' + icon.filename : null,
      cover ? '/uploads/' + cover.filename : null,
      parseInt(req.body.sort_order, 10) || 0,
      req.body.is_active === undefined ? true : bool(req.body.is_active),
      price,
      kindOf(req.body.kind),
    ]);
    res.json({ ok: true, id: r.rows[0].id });
  })
);
admin.put(
  '/topics/:id',
  topicUpload,
  ah(async (req, res) => {
    const { icon: newIcon, cover: newCover } = topicFiles(req);
    const drop = () => { if (newIcon) safeUnlink(UPLOADS, newIcon.filename); if (newCover) safeUnlink(UPLOADS, newCover.filename); };
    const id = parseInt(req.params.id, 10) || 0;
    const old = (await query('SELECT * FROM topics WHERE id=$1', [id])).rows[0];
    if (!old) { drop(); return res.status(404).json({ error: 'Not found' }); }
    const title = cleanStr(req.body.title, 80);
    const price = Number(req.body.price === undefined || req.body.price === '' ? 199 : req.body.price);
    if (!(price > 0) || price > 1000000) { drop(); return res.status(400).json({ error: 'Enter a valid price' }); }
    if (!title) { drop(); return res.status(400).json({ error: 'Enter the name' }); }
    let icon = old.icon_url, cover = old.cover_url;
    if (newIcon) { safeUnlink(UPLOADS, urlFile(icon)); icon = '/uploads/' + newIcon.filename; }
    else if (bool(req.body.remove_icon)) { safeUnlink(UPLOADS, urlFile(icon)); icon = null; }
    if (newCover) { safeUnlink(UPLOADS, urlFile(cover)); cover = '/uploads/' + newCover.filename; }
    else if (bool(req.body.remove_cover)) { safeUnlink(UPLOADS, urlFile(cover)); cover = null; }
    await query('UPDATE topics SET title=$1, icon_url=$2, cover_url=$3, sort_order=$4, is_active=$5, price=$6 WHERE id=$7', [
      title, icon, cover, parseInt(req.body.sort_order, 10) || 0, bool(req.body.is_active), price, id,
    ]);
    res.json({ ok: true });
  })
);
admin.delete(
  '/topics/:id',
  ah(async (req, res) => {
    // content inside is kept (it just becomes "no tab"), so nothing customers bought is lost
    const old = (await query('DELETE FROM topics WHERE id=$1 RETURNING icon_url,cover_url', [parseInt(req.params.id, 10) || 0])).rows[0];
    if (old) { safeUnlink(UPLOADS, urlFile(old.icon_url)); safeUnlink(UPLOADS, urlFile(old.cover_url)); }
    res.json({ ok: true });
  })
);

app.use('/api/admin', admin);

/* ------------------------------ static + errors ------------------------------ */
app.use('/api', (req, res) => res.status(404).json({ error: 'Not found' }));
const IMG_MIME = { '.png': 'image/png', '.jpg': 'image/jpeg', '.webp': 'image/webp', '.gif': 'image/gif' };
app.get('/uploads/:name', ah(async (req, res, next) => {
  const name = req.params.name;
  const mime = IMG_MIME[path.extname(name).toLowerCase()];
  if (!mime || !/^[a-f0-9]{32}\.[a-z]{3,4}$/.test(name)) return next();
  const full = await ensureFile(UPLOADS, name); // restores from the database if the disk was wiped
  if (!full) return next();
  res.sendFile(full, { headers: { 'Content-Type': mime, 'Cache-Control': 'public, max-age=86400', 'Content-Security-Policy': "default-src 'none'; sandbox", 'X-Content-Type-Options': 'nosniff' } });
}));
const PWA_TYPES = { '/manifest.webmanifest': 'application/manifest+json', '/sw.js': 'text/javascript; charset=utf-8', '/icon-192.png': 'image/png', '/icon-512.png': 'image/png', '/icon-maskable.png': 'image/png' };
app.get(Object.keys(PWA_TYPES), (req, res) => {
  res.set({ 'Content-Type': PWA_TYPES[req.path], 'Cache-Control': req.path === '/sw.js' ? 'no-cache' : 'public, max-age=86400' });
  const a = ASSETS[req.path.slice(1)]; res.send(a.t === 'png' ? Buffer.from(a.b, 'base64') : a.b);
});
app.get('/logo.png', (req, res) => { res.set('Cache-Control', 'public, max-age=3600'); res.type('png').send(Buffer.from(ASSETS['logo.png'].b, 'base64')); });
// Website files are served from the embedded ASSETS (nothing else on the server is ever exposed).
function sendAsset(res, key, status) {
  const a = Object.prototype.hasOwnProperty.call(ASSETS, key) ? ASSETS[key] : null;
  if (!a) return false;
  res.set('Cache-Control', 'no-cache');
  res.status(status || 200).type(a.t).send(a.b);
  return true;
}
app.get('/style.css', (req, res, next) => sendAsset(res, 'style.css') || next());
app.get('/js/:name', (req, res, next) => sendAsset(res, 'fe-' + path.basename(req.params.name)) || next());
app.get('/', (req, res) => sendAsset(res, 'index.html'));
app.get('/:page', (req, res, next) => {
  const p = req.params.page.endsWith('.html') ? req.params.page : req.params.page + '.html';
  sendAsset(res, p) || next();
});
app.use((req, res) => { sendAsset(res, '404.html', 404) || res.status(404).send('Not found'); });

app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) return res.status(400).json({ error: err.code === 'LIMIT_FILE_SIZE' ? `File too large (max ${MAX_MB} MB)` : err.message });
  if (err && err.status && err.status < 500) return res.status(err.status).json({ error: err.message });
  if (err && /Only PNG, JPG/.test(err.message)) return res.status(400).json({ error: err.message });
  if (err && err.code === '23505') return res.status(409).json({ error: 'Duplicate entry' });
  logError(err, req);
  res.status(500).json({ error: 'Something went wrong. Please try again.' });
});

process.on('unhandledRejection', (e) => logError(e));
process.on('uncaughtException', (e) => logError(e)); // a single bad request must never take the whole site down

async function bootstrap() {
  // creates / updates tables and default data (safe to run on every start)
  await pool.query(SCHEMA_SQL);
  await pool.query("DELETE FROM audit_log WHERE created_at < now() - interval '180 days'").catch(() => {});
  const email = (process.env.ADMIN_EMAIL || '').trim().toLowerCase();
  const pass = process.env.ADMIN_PASSWORD || '';
  if (email && pass.length >= 10) {
    // creates the admin once; an existing password is never overwritten
    await pool.query(
      `INSERT INTO users(name,email,password_hash,role,email_verified) VALUES ($1,$2,$3,'admin',true)
       ON CONFLICT (email) DO UPDATE SET role='admin', email_verified=true`,
      [process.env.ADMIN_NAME || 'Super Admin', email, await bcrypt.hash(pass, 12)]
    );
    console.log('Admin account ready:', email);
  } else {
    console.log('ADMIN_EMAIL / ADMIN_PASSWORD (min 10 chars) not set - no admin created.');
  }
}

if (require.main === module) {
  bootstrap()
    .then(() => app.listen(PORT, () => console.log(`NextBiz Digital Company running on port ${PORT}`)))
    .catch((e) => { logError(e); console.error('Startup failed:', e.message); process.exit(1); });
}
module.exports = app;
